CREATE OR REPLACE FUNCTION collect_hybrid.require_roster_caller()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare sid text:=auth.jwt()->>'session_id';
begin
 perform public._lock_notification_session_gate();
 if auth.role() is distinct from 'authenticated' or auth.uid() is null or sid is null
  or sid !~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' then
  raise exception 'roster_session_required' using errcode='42501'; end if;
 perform collect_hybrid.require_roster_actor(auth.uid(),sid::uuid);
 return sid::uuid;
end $function$

_lock_notification_registration_session(.definition:
CREATE OR REPLACE FUNCTION public._lock_notification_registration_session()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare session_text text:=auth.jwt()->>'session_id'; session_id uuid; begin
  perform public._lock_notification_session_gate();
  if auth.role() is distinct from 'authenticated' or auth.uid() is null
    or session_text is null or session_text !~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' then
    raise exception 'notification_registration_session_required' using errcode='42501';
  end if;
  session_id:=session_text::uuid;
  -- SHARE blocks both deletion and non-key revocation updates before we lock
  -- a token. A late registration sees the deletion after waiting and refuses.
  perform 1 from auth.sessions s where s.id=session_id and s.user_id=auth.uid() for share;
  if not found or not public._notification_session_is_live(session_id,auth.uid()) then
    raise exception 'notification_registration_session_required' using errcode='42501';
  end if;
  return session_id;
end $function$

